function spawnTracer(startVec, endVec, category = 'rifle') {
  if (!Number.isFinite(startVec.x) || !Number.isFinite(endVec.x)) return;
  const delta = new THREE.Vector3().subVectors(endVec, startVec);
  const totalDist = delta.length();
  if (totalDist < 0.25) return;

  while (activeTracers.length >= VFX_CAPS.maxTracers) {
    const old = activeTracers.shift();
    scene.remove(old.mesh);
  }

  const isSniper = category === 'sniper';
  const streakLen = Math.min(totalDist, isSniper ? 5.5 : 2.6);
  const mesh = new THREE.Mesh(
    isSniper ? VFX_SHARED.tracerSniperGeo : VFX_SHARED.tracerGeo,
    isSniper ? VFX_SHARED.tracerMatSniper : VFX_SHARED.tracerMatDefault
  );
  const visualWidth=isSniper?.68:category==='pistol'?.54:category==='smg'?.60:.75;
  mesh.scale.set(visualWidth, streakLen, visualWidth);
  const dir = delta.clone().divideScalar(totalDist);
  mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
  mesh.position.copy(startVec).addScaledVector(dir, streakLen * 0.5);
  scene.add(mesh);

  const speed = isSniper ? 240 : 175;
  const life = Math.min(0.24, Math.max(0.045, totalDist / speed));
  activeTracers.push({
    mesh,
    start: startVec.clone(),
    end: endVec.clone(),
    dir,
    totalDist,
    streakLen,
    visualWidth,visualTracerKind:isSniper?1:0,
    life,
    maxLife: life
  });
}

