function spawnCharacterHitFX(pos, isHead = false, distance = 10) {
  if (!pos || ![pos.x, pos.y, pos.z].every(Number.isFinite)) return;
  const distScale = Math.max(0.75, Math.min(1.55, 0.75 + distance * 0.018));
  const mat = isHead ? VFX_SHARED.matBloodHead : VFX_SHARED.matBloodBody;
  const count = isHead ? 7 : 5;
  for (let i = 0; i < count && activeParticles.length < VFX_CAPS.maxParticles; i++) {
    const mesh = new THREE.Mesh(VFX_SHARED.bloodDropGeo, mat);
    mesh.position.copy(pos);
    // V275: compact existing hit feedback, deterministic size variation.
    const size=(isHead?1.0:.82)*Math.min(1.30,distScale);
    mesh.scale.setScalar(size*(.90+(i%3)*.08));
    scene.add(mesh);
    const life = 0.24 + Math.random() * 0.10;
    activeParticles.push({
      mesh,
      vel: new THREE.Vector3(
        (Math.random() - 0.5) * 3.8,
        0.9 + Math.random() * 2.4,
        (Math.random() - 0.5) * 3.8
      ),
      gravity: 11.0,
      growRate: -0.08,
      alignVel: false,
      life,
      maxLife: life
    });
  }
}

function spawnImpactFX(pos, normal, isMetal = false, dist = 10) {
  if (!Number.isFinite(pos.x)) return;
  const n = (normal && normal.lengthSq() > 0.001) ? normal.clone().normalize() : new THREE.Vector3(0, 1, 0);
  const distScale = Math.max(0.75, Math.min(1.55, 0.72 + dist * 0.022));

  spawnImpactMark(pos, n, isMetal);

  if (isMetal) {
    if (activeParticles.length < VFX_CAPS.maxParticles) {
      const assets=getV277ImpactAssets();
      const flash = new THREE.Mesh(assets.quad,assets.base.flash);
      flash.userData.v277Impact='flash';
      flash.quaternion.copy(camera.quaternion);
      flash.position.copy(pos).addScaledVector(n, 0.04);
      flash.scale.setScalar(distScale);
      scene.add(flash);
      activeParticles.push({
        mesh: flash,
        vel: new THREE.Vector3(0, 0, 0),
        gravity: 0,
        growRate: 3.5,
        alignVel: false,
        life: 0.14,
        maxLife: 0.14
      });
    }

    const sparkCount = 7;
    for (let i = 0; i < sparkCount && activeParticles.length < VFX_CAPS.maxParticles; i++) {
      const m = new THREE.Mesh(
        VFX_SHARED.sparkGeo,
        i < 3 ? VFX_SHARED.sparkHotMat : VFX_SHARED.sparkWarmMat
      );
      m.userData.v277Impact=i<3?'sparkHot':'sparkWarm';
      m.position.copy(pos).addScaledVector(n, 0.03);
      m.scale.set(.68*distScale,.68*distScale,distScale);
      const vel = new THREE.Vector3(
        n.x * (2.6 + Math.random() * 3.8) + (Math.random() - 0.5) * 4.2,
        n.y * (2.2 + Math.random() * 3.6) + Math.random() * 2.4,
        n.z * (2.6 + Math.random() * 3.8) + (Math.random() - 0.5) * 4.2
      );
      scene.add(m);
      const life = 0.18 + Math.random() * 0.14;
      activeParticles.push({
        mesh: m,
        vel,
        gravity: 14,
        growRate: 0,
        alignVel: true,
        life,
        maxLife: life
      });
    }
  } else {
    for (let d = 0; d < 2 && activeParticles.length < VFX_CAPS.maxParticles; d++) {
      const assets=getV277ImpactAssets();
      const dust = new THREE.Mesh(assets.quad,assets.base.dust);
      dust.userData.v277Impact='dust';
      dust.quaternion.copy(camera.quaternion);
      dust.position.copy(pos).addScaledVector(n, 0.06 + d * 0.05);
      dust.scale.setScalar((0.9 + d * 0.4) * distScale);
      scene.add(dust);
      const life = 0.36 + d * 0.10;
      activeParticles.push({
        mesh: dust,
        vel: new THREE.Vector3(
          n.x * 0.8 + (Math.random() - 0.5) * 0.9,
          0.55 + Math.random() * 0.65,
          n.z * 0.8 + (Math.random() - 0.5) * 0.9
        ),
        gravity: -0.4,
        growRate: 4.8,
        alignVel: false,
        life,
        maxLife: life
      });
    }

    const chipCount = 4;
    for (let i = 0; i < chipCount && activeParticles.length < VFX_CAPS.maxParticles; i++) {
      const chip = new THREE.Mesh(VFX_SHARED.chipGeo, VFX_SHARED.chipMat);
      chip.position.copy(pos).addScaledVector(n, 0.04);
      chip.scale.setScalar((0.75 + Math.random() * 0.5) * distScale);
      const vel = new THREE.Vector3(
        n.x * (1.8 + Math.random() * 2.6) + (Math.random() - 0.5) * 3.0,
        n.y * (1.6 + Math.random() * 2.4) + 1.4 + Math.random() * 1.6,
        n.z * (1.8 + Math.random() * 2.6) + (Math.random() - 0.5) * 3.0
      );
      scene.add(chip);
      const life = 0.28 + Math.random() * 0.16;
      activeParticles.push({
        mesh: chip,
        vel,
        gravity: 15,
        growRate: 0,
        alignVel: false,
        life,
        maxLife: life
      });
    }
  }
}

function spawnShellCasing(ejectPos, camQuat, category) {
  if (category === 'melee' || category === 'rocket' || category === 'grenade' || category === 'medkit' || category === 'claymore' || category === 'drone') return;
  while (activeShellCasings.length >= VFX_CAPS.maxCasings) {
    const old = activeShellCasings.shift();
    scene.remove(old.mesh);
  }
  const mesh = new THREE.Mesh(V279_CASING_GEO,V279_CASING_MAT);
  mesh.position.copy(ejectPos);
  mesh.quaternion.copy(camQuat);
  const right = new THREE.Vector3(1, 0, 0).applyQuaternion(camQuat);
  const up = new THREE.Vector3(0, 1, 0).applyQuaternion(camQuat);
  const vel = new THREE.Vector3()
    .addScaledVector(right, 1.5 + Math.random() * 0.9)
    .addScaledVector(up, 1.1 + Math.random() * 0.7);
  scene.add(mesh);
  activeShellCasings.push({
    mesh,
    vel,
    rotVel: new THREE.Vector3(12 + Math.random() * 14, 10 + Math.random() * 12, 8),
    life: 1.35
  });
}

