function foReleaseEquipment(entity,scene){
 if(!entity||!entity.mesh||entity.foReleased)return;
 entity.foReleased=true;
 const root=entity.mesh,geometries=new Set();
 const collect=n=>{if(n.geometry)geometries.add(n.geometry);};
 if(typeof root.traverse==='function')root.traverse(collect);else collect(root);
 scene.remove(root);
 for(const geo of geometries)if(typeof geo.dispose==='function')geo.dispose();
 for(const mat of new Set(entity.ownedMaterials||[]))if(typeof mat?.dispose==='function')mat.dispose();
}

function clearAllMatchEntities() {
  resetV278DamageFlash();
  [activeGrenades, activeRockets, activeMedkits, activeClaymores, activeTracers, activeParticles, activeImpactMarks, activeShellCasings].forEach((list) => {
    for (let i = list.length - 1; i >= 0; i--) {
      if(list[i]&&list[i].mesh){
        if(list===activeGrenades||list===activeRockets||list===activeMedkits||list===activeClaymores)foReleaseEquipment(list[i],scene);
        else scene.remove(list[i].mesh);
      }
    }
    list.length = 0;
  });
}

