function throwGrenade(origin, dir, ownerName, team) {
  const mesh = new THREE.Mesh(new THREE.SphereGeometry(0.085, 10, 10), WEAPON_MATS.olivePaint);
  // The caller supplies a short forward spawn offset; sweep it too.
  const launchOffset=ownerName===player.name?.55:.5;
  const launchDir=dir.clone().normalize(),launchBase=origin.clone().addScaledVector(launchDir,-launchOffset);
  const launchHit=foGrenadeSweep(launchBase,launchDir.x*launchOffset,launchDir.y*launchOffset,launchDir.z*launchOffset,mapColliders);
  if(launchHit){
    origin=launchBase.addScaledVector(launchDir,launchOffset*launchHit.t);
    origin.x+=launchHit.nx*launchHit.push;origin.y+=launchHit.ny*launchHit.push;origin.z+=launchHit.nz*launchHit.push;
  }
  mesh.position.copy(origin);
  scene.add(mesh);

  const vel = dir.clone().normalize().multiplyScalar(17.5);
  vel.y += 4.2;

  activeGrenades.push({
    mesh,
    pos: origin.clone(),
    vel,
    ownerName,
    team,
    fuse: 2.3
  });
}

