function fireRocket(origin, dir, ownerName, team) {
  const g = new THREE.Group();
  const body = new THREE.Mesh(new THREE.CylinderGeometry(0.042, 0.042, 0.34, 8), WEAPON_MATS.olivePaint);
  body.rotation.x = Math.PI / 2;
  g.add(body);
  const nose = new THREE.Mesh(new THREE.ConeGeometry(0.042, 0.10, 8), WEAPON_MATS.brass);
  nose.rotation.x = Math.PI / 2;
  nose.position.z = 0.22;
  g.add(nose);

  const nDir = dir.clone().normalize();
  const offset=ownerName===player.name?.75:.7;
  const launchBase=origin.clone().addScaledVector(nDir,-offset);
  const launchHit=foRocketSurface(launchBase,nDir.x*offset,nDir.y*offset,nDir.z*offset,mapColliders,foWorldX(39.5),foWorldZ(60.5));
  if(launchHit)origin=foPlaceRocketContact(origin.clone(),launchBase,nDir.x*offset,nDir.y*offset,nDir.z*offset,launchHit);
  g.position.copy(origin);
  g.quaternion.setFromUnitVectors(new THREE.Vector3(0, 0, 1), nDir);
  scene.add(g);

  activeRockets.push({
    mesh: g,
    pos: origin.clone(),
    vel: nDir.multiplyScalar(44.0),
    ownerName,
    team,
    life: 3.5,
    launchBlocked:!!launchHit
  });
}

