function updateEntitiesAndFX(dt) {
  for (let i = activeGrenades.length - 1; i >= 0; i--) {
    const g = activeGrenades[i];
    g.fuse -= dt;
    foAdvanceGrenade(g,dt,mapColliders,getFloorHeightAt);

    if (Math.abs(g.pos.x) > foWorldX(39)) g.vel.x *= -0.5;
    if (Math.abs(g.pos.z) > foWorldZ(60)) g.vel.z *= -0.5;

    g.mesh.position.copy(g.pos);
    g.mesh.rotation.x += 6 * dt;
    g.mesh.rotation.z += 5 * dt;

    if (g.fuse <= 0) {
      triggerExplosion(g.pos, 6.0, 115, g.ownerName, g.team, 'M67 BOMBA');
      foReleaseEquipment(g,scene);
      activeGrenades.splice(i, 1);
    }
  }

  for (let i = activeRockets.length - 1; i >= 0; i--) {
    const r = activeRockets[i];
    r.life -= dt;
    const step = r.vel.clone().multiplyScalar(dt);
    const nextPos = r.pos.clone().add(step);

    let detonated = r.life<=0||r.launchBlocked;
    if(r.launchBlocked)nextPos.copy(r.pos);
    else{
      const hit=foRocketSurface(r.pos,step.x,step.y,step.z,mapColliders,foWorldX(39.5),foWorldZ(60.5));
      if(hit){foPlaceRocketContact(nextPos,r.pos,step.x,step.y,step.z,hit);detonated=true;}
    }
    if (!detonated && player.alive && player.team !== r.team) {
      const pCenter = new THREE.Vector3(player.pos.x, player.pos.y + (player.crouching ? 0.65 : 0.95), player.pos.z);
      if (distSqPointToSegment(pCenter, r.pos, nextPos) < 0.85 * 0.85) {
        nextPos.copy(pCenter);
        detonated = true;
      }
    }
    if (!detonated) {
      for (let b = 0; b < bots.length; b++) {
        if (bots[b].alive && bots[b].team !== r.team) {
          const bCenter = new THREE.Vector3(bots[b].pos.x, bots[b].pos.y + 1.0, bots[b].pos.z);
          if (distSqPointToSegment(bCenter, r.pos, nextPos) < 0.85 * 0.85) {
            nextPos.copy(bCenter);
            detonated = true;
            break;
          }
        }
      }
    }
    if (!detonated) {
      for (let dIdx = 0; dIdx < droneSystem.activeDrones.length; dIdx++) {
        const dr = droneSystem.activeDrones[dIdx];
        if (!dr || dr.resolved) continue;
        if (!DRONE_CONFIG.friendlyFire && dr.team === r.team) continue;
        const hitRad = DRONE_CONFIG.hitboxRadius + 0.45;
        if (distSqPointToSegment(dr.pos, r.pos, nextPos) < hitRad * hitRad) {
          nextPos.copy(dr.pos);
          detonated = true;
          break;
        }
      }
    }

    r.pos.copy(nextPos);
    r.mesh.position.copy(r.pos);

    if (!detonated && activeParticles.length < VFX_CAPS.maxParticles && Math.random() < 0.65) {
      const smoke = new THREE.Mesh(VFX_SHARED.dustGeo, VFX_SHARED.dustMat);
      smoke.position.copy(r.pos);
      smoke.scale.setScalar(1.1);
      scene.add(smoke);
      activeParticles.push({
        mesh: smoke,
        vel: new THREE.Vector3((Math.random() - 0.5) * 0.6, 0.4, (Math.random() - 0.5) * 0.6),
        gravity: -0.2,
        growRate: 3.2,
        alignVel: false,
        life: 0.30,
        maxLife: 0.30
      });
    }

    if (detonated) {
      triggerExplosion(r.pos, 6.5, 125, r.ownerName, r.team, 'CARL GUSTAF');
      foReleaseEquipment(r,scene);
      activeRockets.splice(i, 1);
    }
  }

  for (let i = activeMedkits.length - 1; i >= 0; i--) {
    const mk = activeMedkits[i];
    mk.life -= dt;
    mk.healTick -= dt;
    const pulse = 1 + Math.sin(performance.now() * 0.008) * 0.05;
    mk.ring.scale.set(pulse, pulse, 1);

    if (mk.healTick <= 0) {
      mk.healTick = 0.5;
      if (player.alive && player.team === mk.team && player.hp < player.maxHp && foMedkitReachable(mk.pos,player.pos,mapColliders)) {
        player.hp = Math.min(player.maxHp, player.hp + 10);
        sound.playHeal();
        const hf = document.getElementById('heal-flash');
        hf.style.opacity = '0.75';
        setTimeout(() => { hf.style.opacity = '0'; }, 180);
        updateHUD();
      }
      for (let b = 0; b < bots.length; b++) {
        const ally = bots[b];
        if (ally.alive && ally.team === mk.team && ally.hp < ally.maxHp && foMedkitReachable(mk.pos,ally.pos,mapColliders)) {
          ally.hp = Math.min(ally.maxHp, ally.hp + 10);
        }
      }
    }

    if (mk.life <= 0) {
      foReleaseEquipment(mk,scene);
      activeMedkits.splice(i, 1);
    }
  }

  for (let i = activeClaymores.length - 1; i >= 0; i--) {
    const cm = activeClaymores[i];
    cm.life -= dt;
    if (cm.armTimer > 0) {
      cm.armTimer -= dt;
      continue;
    }

    let triggered = false;
    const mineEye = cm.pos.clone().add(new THREE.Vector3(0, 0.35, 0));
    const fwdX = Math.sin(cm.yaw);
    const fwdZ = Math.cos(cm.yaw);

    if (player.alive && player.team !== cm.team) {
      const dx = player.pos.x - cm.pos.x;
      const dz = player.pos.z - cm.pos.z;
      const d = Math.hypot(dx, dz);
      if (d < 3.4 && (dx * fwdX + dz * fwdZ) / Math.max(0.1, d) > 0.45 && hasLineOfSight(mineEye, camera.position)) {
        triggered = true;
      }
    }

    if (!triggered) {
      for (let b = 0; b < bots.length; b++) {
        const eb = bots[b];
        if (!eb.alive || eb.team === cm.team) continue;
        const dx = eb.pos.x - cm.pos.x;
        const dz = eb.pos.z - cm.pos.z;
        const d = Math.hypot(dx, dz);
        if (d < 3.4 && (dx * fwdX + dz * fwdZ) / Math.max(0.1, d) > 0.45 && hasLineOfSight(mineEye, eb.pos.clone().add(new THREE.Vector3(0, 1.0, 0)))) {
          triggered = true;
          break;
        }
      }
    }

    if (triggered) {
      triggerExplosion(cm.pos, 4.2, 120, cm.ownerName, cm.team, 'CLAYMORE');
      foReleaseEquipment(cm,scene);
      activeClaymores.splice(i, 1);
    } else if (cm.life <= 0) {
      foReleaseEquipment(cm,scene);
      activeClaymores.splice(i, 1);
    }
  }

  for (let i = activeTracers.length - 1; i >= 0; i--) {
    const tr = activeTracers[i];
    tr.life -= dt;
    const prog = 1 - Math.max(0, tr.life / tr.maxLife);
    const travelDist = prog * Math.max(0, tr.totalDist - tr.streakLen);
    tr.mesh.position.copy(tr.start).addScaledVector(tr.dir, travelDist + tr.streakLen * 0.5);
    if(tr.life>0){
      const t=Math.max(0,Math.min(1,tr.life/tr.maxLife)),width=tr.visualWidth*(.58+.42*t);
      tr.mesh.scale.x=width;tr.mesh.scale.z=width;
      tr.mesh.material=V279_TRACER_MATS[tr.visualTracerKind][t>.65?0:t>.38?1:t>.13?2:3];
    }
    if (tr.life <= 0) {
      scene.remove(tr.mesh);
      activeTracers.splice(i, 1);
    }
  }

  for (let i = activeParticles.length - 1; i >= 0; i--) {
    const p = activeParticles[i];
    p.life -= dt;
    p.vel.y -= p.gravity * dt;
    p.mesh.position.addScaledVector(p.vel, dt);
    if (p.growRate !== 0) {
      const s = Math.max(0.05, p.mesh.scale.x + p.growRate * dt);
      p.mesh.scale.setScalar(s);
    }
    if (p.alignVel && p.vel.lengthSq() > 0.01) {
      p.mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 0, 1), p.vel.clone().normalize());
    }
    if(p.mesh.userData.v277Impact&&p.life>0)applyV277ParticleVisual(p);
    if (p.life <= 0) {
      scene.remove(p.mesh);
      activeParticles.splice(i, 1);
    }
  }

  for (let i = activeImpactMarks.length - 1; i >= 0; i--) {
    activeImpactMarks[i].life -= dt;
    const mark=activeImpactMarks[i],kind=mark.mesh.userData.v277Mark;
    if(kind&&mark.life>0){
      const t=mark.life/2.2;
      mark.mesh.material=getV277ImpactAssets().fades[kind][t>.30?0:t>.18?1:t>.07?2:3];
    }
    if (activeImpactMarks[i].life <= 0) {
      scene.remove(activeImpactMarks[i].mesh);
      activeImpactMarks.splice(i, 1);
    }
  }

  for (let i = activeShellCasings.length - 1; i >= 0; i--) {
    const sc = activeShellCasings[i];
    sc.life -= dt;
    foAdvanceCasing(sc,dt,mapColliders,getFloorHeightAt);
    sc.mesh.rotation.x += sc.rotVel.x * dt;
    sc.mesh.rotation.y += sc.rotVel.y * dt;
    if (sc.life <= 0) {
      scene.remove(sc.mesh);
      activeShellCasings.splice(i, 1);
    }
  }

  if (dustParticles) {
    const posAttr = dustParticles.geometry.attributes.position;
    for (let i = 0; i < posAttr.count; i++) {
      let z = posAttr.getZ(i) + 0.55 * dt;
      if (z > 46) z = -46;
      posAttr.setZ(i, z);
    }
    posAttr.needsUpdate = true;
  }
}
